CREATE OR REPLACE FUNCTION public.advance_sale_status(p_sale_id uuid, p_order_status text DEFAULT NULL::text, p_fulfillment_status text DEFAULT NULL::text)
 RETURNS sales
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare sale_record public.sales;
begin
  if (select auth.uid()) is null then raise exception using message = 'AUTHORIZATION_REQUIRED'; end if;
  if not exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin') then raise exception using message = 'ADMIN_AUTHORIZATION_REQUIRED'; end if;
  select * into sale_record from public.sales where id = p_sale_id for update;
  if not found then raise exception using message = 'SALE_NOT_FOUND'; end if;
  if sale_record.order_status = 'cancelled' then raise exception using message = 'SALE_ALREADY_CANCELLED'; end if;
  if p_order_status is not null and p_order_status not in ('confirmed', 'completed', 'cancelled') then raise exception using message = 'ORDER_STATUS_INVALID'; end if;
  if p_fulfillment_status is not null and p_fulfillment_status not in ('pending', 'preparing', 'ready', 'delivered') then raise exception using message = 'FULFILLMENT_STATUS_INVALID'; end if;
  if p_order_status = 'completed' and sale_record.fulfillment_status <> 'delivered' then raise exception using message = 'SALE_NOT_DELIVERED'; end if;
  update public.sales set order_status = coalesce(p_order_status, order_status), fulfillment_status = coalesce(p_fulfillment_status, fulfillment_status), completed_at = case when p_order_status = 'completed' then timezone('utc', now()) else completed_at end, cancelled_at = case when p_order_status = 'cancelled' then timezone('utc', now()) else cancelled_at end, updated_at = timezone('utc', now()) where id = p_sale_id returning * into sale_record;
  return sale_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_sale(p_sale_id uuid, p_return_stock boolean, p_reason text, p_operation_key uuid)
 RETURNS sales
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare sale_record public.sales; stock_movement record; reversal public.inventory_movements; existing_adjustment public.sale_adjustments;
begin
  if (select auth.uid()) is null then raise exception using message = 'AUTHORIZATION_REQUIRED'; end if;
  if not exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin') then raise exception using message = 'ADMIN_AUTHORIZATION_REQUIRED'; end if;
  select * into sale_record from public.sales where id = p_sale_id for update;
  if not found then raise exception using message = 'SALE_NOT_FOUND'; end if;
  if sale_record.order_status = 'cancelled' then return sale_record; end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then raise exception using message = 'CANCELLATION_REASON_REQUIRED'; end if;
  if sale_record.order_status = 'draft' then update public.sales set order_status = 'cancelled', cancelled_at = timezone('utc', now()), updated_at = timezone('utc', now()) where id = p_sale_id returning * into sale_record; return sale_record; end if;
  if p_return_stock then
    for stock_movement in select * from public.inventory_movements where source_type = 'sale' and source_id = p_sale_id order by created_at
    loop
      if not exists (select 1 from public.sale_stock_reversals where original_movement_id = stock_movement.id) then
        reversal := public.register_inventory_movement(stock_movement.inventory_item_id, 'manual_in', abs(stock_movement.quantity_delta), stock_movement.unit_cost_snapshot, 'Reversão da venda #' || sale_record.order_number::text, gen_random_uuid());
        update public.inventory_movements set source_type = 'reversal', source_id = p_sale_id where id = reversal.id;
        insert into public.sale_stock_reversals(sale_id, original_movement_id, reversal_movement_id, created_by) values (p_sale_id, stock_movement.id, reversal.id, (select auth.uid()));
      end if;
    end loop;
  end if;
  insert into public.sale_adjustments(sale_id, adjustment_type, amount, reason, created_by, operation_key) values (p_sale_id, case when p_return_stock then 'stock_reversal' else 'cancellation' end, case when p_return_stock then 0 else sale_record.total_amount end, btrim(p_reason), (select auth.uid()), coalesce(p_operation_key, gen_random_uuid())) on conflict (operation_key) do nothing;
  update public.sales set order_status = 'cancelled', cancelled_at = timezone('utc', now()), updated_at = timezone('utc', now()) where id = p_sale_id returning * into sale_record;
  return sale_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_sale(p_sale_id uuid, p_manual_discount numeric DEFAULT 0, p_discount_reason text DEFAULT NULL::text, p_pricing jsonb DEFAULT '{"items": [], "promotions": []}'::jsonb, p_operation_key uuid DEFAULT NULL::uuid)
 RETURNS sales
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare sale_record public.sales; sale_item record; priced jsonb; applied_promotion record; promotion_record public.promotions; variant_record record; recipe_ingredient record; quantity_consumed numeric; ingredient_cost numeric; total_cogs numeric := 0; any_unknown boolean := false; item_unknown boolean; base_subtotal numeric := 0; final_subtotal numeric := 0; item_discount_total numeric := 0; promotion_discount_total numeric := 0; item_count integer := 0;
begin
  if (select auth.uid()) is null then raise exception using message = 'AUTHORIZATION_REQUIRED'; end if;
  if not exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin') then raise exception using message = 'ADMIN_AUTHORIZATION_REQUIRED'; end if;
  select * into sale_record from public.sales where id = p_sale_id for update;
  if not found then raise exception using message = 'SALE_NOT_FOUND'; end if;
  if sale_record.order_status = 'confirmed' or sale_record.order_status = 'completed' then return sale_record; end if;
  if sale_record.order_status <> 'draft' then raise exception using message = 'SALE_NOT_DRAFT'; end if;
  if p_manual_discount < 0 or p_manual_discount > 0 and nullif(btrim(coalesce(p_discount_reason, '')), '') is null then raise exception using message = 'MANUAL_DISCOUNT_REASON_REQUIRED'; end if;
  if p_manual_discount > 0 and p_manual_discount > coalesce((select sum((value->>'final_total')::numeric) from jsonb_array_elements(coalesce(p_pricing->'items', '[]'::jsonb))), 0) then raise exception using message = 'MANUAL_DISCOUNT_EXCEEDS_TOTAL'; end if;

  for sale_item in select si.* from public.sale_items si where si.sale_id = p_sale_id order by si.created_at, si.id
  loop
    item_count := item_count + 1;
    priced := (select value from jsonb_array_elements(coalesce(p_pricing->'items', '[]'::jsonb)) where value->>'sale_item_id' = sale_item.id::text limit 1);
    if priced is null then raise exception using message = 'SALE_PRICING_INCOMPLETE'; end if;
    if (priced->>'quantity')::integer <> sale_item.quantity then raise exception using message = 'SALE_PRICING_QUANTITY_INVALID'; end if;
    select pv.*, p.company_id, p.name as product_name, p.is_active as product_active into variant_record from public.product_variants pv join public.products p on p.id = pv.product_id where pv.id = sale_item.product_variant_id for update;
    if not found or not variant_record.is_active or not variant_record.product_active or variant_record.company_id <> sale_record.company_id then raise exception using message = 'SALE_VARIANT_INVALID'; end if;
    if abs(variant_record.price - (priced->>'unit_price_snapshot')::numeric) > 0.000001 then raise exception using message = 'SALE_PRICING_STALE_RETRY'; end if;
    if (priced->>'final_total')::numeric < 0 or (priced->>'original_subtotal')::numeric < 0 then raise exception using message = 'SALE_TOTAL_INVALID'; end if;
    if coalesce((priced->>'discount_allocated')::numeric, 0) < 0 or abs((priced->>'original_subtotal')::numeric - coalesce((priced->>'discount_allocated')::numeric, 0) - (priced->>'final_total')::numeric) > 0.000001 then raise exception using message = 'SALE_ITEM_DISCOUNT_INVALID'; end if;
    base_subtotal := base_subtotal + (priced->>'original_subtotal')::numeric;
    final_subtotal := final_subtotal + (priced->>'final_total')::numeric;
    item_discount_total := item_discount_total + coalesce((priced->>'discount_allocated')::numeric, 0);
    update public.sale_items set product_name_snapshot = variant_record.product_name, variant_name_snapshot = variant_record.name, unit_price_snapshot = variant_record.price, original_subtotal = (priced->>'original_subtotal')::numeric, discount_allocated = coalesce((priced->>'discount_allocated')::numeric, 0), final_total = (priced->>'final_total')::numeric, recipe_version_id = variant_record.recipe_version_id, recipe_scale_snapshot = variant_record.recipe_scale where id = sale_item.id;
    item_unknown := false;
    if variant_record.recipe_version_id is null then
      any_unknown := true;
      item_unknown := true;
      update public.sale_items set cost_status_snapshot = 'unknown', estimated_unit_cost_snapshot = null, estimated_total_cost_snapshot = null where id = sale_item.id;
      continue;
    end if;
    ingredient_cost := 0;
    for recipe_ingredient in select rvi.*, ii.name, ii.average_unit_cost from public.recipe_version_ingredients rvi join public.inventory_items ii on ii.id = rvi.inventory_item_id where rvi.recipe_version_id = variant_record.recipe_version_id
    loop
      quantity_consumed := recipe_ingredient.quantity_base * variant_record.recipe_scale * sale_item.quantity;
      if recipe_ingredient.average_unit_cost is null or recipe_ingredient.average_unit_cost <= 0 then any_unknown := true; item_unknown := true; insert into public.sale_item_ingredient_snapshots(sale_item_id, inventory_item_id, ingredient_name_snapshot, quantity_consumed, unit_cost_snapshot, total_cost_snapshot, cost_status) values (sale_item.id, recipe_ingredient.inventory_item_id, recipe_ingredient.name, quantity_consumed, null, null, 'unknown');
      else ingredient_cost := ingredient_cost + recipe_ingredient.average_unit_cost * recipe_ingredient.quantity_base * variant_record.recipe_scale; insert into public.sale_item_ingredient_snapshots(sale_item_id, inventory_item_id, ingredient_name_snapshot, quantity_consumed, unit_cost_snapshot, total_cost_snapshot, cost_status) values (sale_item.id, recipe_ingredient.inventory_item_id, recipe_ingredient.name, quantity_consumed, recipe_ingredient.average_unit_cost, recipe_ingredient.average_unit_cost * quantity_consumed, 'known'); end if;
      perform public.register_sale_stock_movement(recipe_ingredient.inventory_item_id, quantity_consumed, coalesce(recipe_ingredient.average_unit_cost, 0), 'Venda #' || sale_record.order_number::text || ' confirmada', gen_random_uuid(), p_sale_id);
    end loop;
    update public.sale_items set estimated_unit_cost_snapshot = case when ingredient_cost > 0 then ingredient_cost else null end, estimated_total_cost_snapshot = case when ingredient_cost > 0 then ingredient_cost * sale_item.quantity else null end, cost_status_snapshot = case when ingredient_cost > 0 and not item_unknown then 'complete' when ingredient_cost > 0 then 'partial' else 'unknown' end where id = sale_item.id;
    total_cogs := total_cogs + ingredient_cost * sale_item.quantity;
  end loop;
  if item_count = 0 or abs(base_subtotal - coalesce((select sum((value->>'original_subtotal')::numeric) from jsonb_array_elements(coalesce(p_pricing->'items', '[]'::jsonb))), 0)) > 0.000001 then raise exception using message = 'SALE_PRICING_TOTAL_INVALID'; end if;
  if final_subtotal - p_manual_discount < 0 then raise exception using message = 'SALE_TOTAL_INVALID'; end if;
  for applied_promotion in select * from jsonb_to_recordset(coalesce(p_pricing->'promotions', '[]'::jsonb)) as x(promotion_id uuid, promotion_name_snapshot text, bundle_quantity integer, bundle_price numeric, discount_amount numeric, variant_ids_snapshot jsonb)
  loop
    select * into promotion_record from public.promotions where id = applied_promotion.promotion_id and company_id = sale_record.company_id and is_active for share;
    if not found or promotion_record.bundle_quantity <> applied_promotion.bundle_quantity or abs(promotion_record.bundle_price - applied_promotion.bundle_price) > 0.000001 or applied_promotion.discount_amount < 0 then raise exception using message = 'SALE_PROMOTION_INVALID'; end if;
    promotion_discount_total := promotion_discount_total + applied_promotion.discount_amount;
    insert into public.sale_applied_promotions(sale_id, promotion_id, promotion_name_snapshot, bundle_quantity, bundle_price, discount_amount, variant_ids_snapshot) values (p_sale_id, applied_promotion.promotion_id, applied_promotion.promotion_name_snapshot, applied_promotion.bundle_quantity, applied_promotion.bundle_price, greatest(applied_promotion.discount_amount, 0), coalesce(applied_promotion.variant_ids_snapshot, '[]'::jsonb));
  end loop;
  if abs(item_discount_total - promotion_discount_total - p_manual_discount) > 0.000001 then raise exception using message = 'SALE_DISCOUNT_TOTAL_INVALID'; end if;
  update public.sales set subtotal = base_subtotal, discount_total = greatest(base_subtotal - final_subtotal, 0) + p_manual_discount, total_amount = final_subtotal - p_manual_discount, estimated_cogs = case when any_unknown then null else total_cogs end, order_status = 'confirmed', confirmed_at = timezone('utc', now()), confirmation_operation_key = coalesce(p_operation_key, gen_random_uuid()), updated_at = timezone('utc', now()) where id = p_sale_id returning * into sale_record;
  if p_manual_discount > 0 then insert into public.sale_adjustments(sale_id, adjustment_type, amount, reason, created_by, operation_key) values (p_sale_id, 'manual_discount', p_manual_discount, btrim(p_discount_reason), (select auth.uid()), coalesce(p_operation_key, gen_random_uuid())); end if;
  return sale_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_purchase_draft(p_supplier_id uuid, p_company_id uuid, p_purchase_date date, p_notes text, p_additional_costs numeric, p_discount numeric, p_items jsonb)
 RETURNS purchases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  purchase_record public.purchases;
  purchase_item record;
  item_count integer := 0;
begin
  if (select auth.uid()) is null then raise exception using message = 'AUTHORIZATION_REQUIRED'; end if;
  if not exists (select 1 from public.profiles where profiles.id = (select auth.uid()) and profiles.role = 'admin') then raise exception using message = 'ADMIN_AUTHORIZATION_REQUIRED'; end if;
  if p_supplier_id is null or not exists (select 1 from public.suppliers where id = p_supplier_id and is_active) then raise exception using message = 'ACTIVE_SUPPLIER_REQUIRED'; end if;
  if coalesce(p_additional_costs, 0) < 0 or coalesce(p_discount, 0) < 0 then raise exception using message = 'PURCHASE_COST_INVALID'; end if;
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' then raise exception using message = 'PURCHASE_ITEMS_INVALID'; end if;

  insert into public.purchases (supplier_id, company_id, purchase_date, notes, additional_costs, discount, created_by)
  values (p_supplier_id, p_company_id, coalesce(p_purchase_date, current_date), nullif(btrim(coalesce(p_notes, '')), ''), coalesce(p_additional_costs, 0), coalesce(p_discount, 0), (select auth.uid()))
  returning * into purchase_record;

  for purchase_item in select * from jsonb_to_recordset(coalesce(p_items, '[]'::jsonb)) as x(inventory_item_id uuid, quantity numeric, unit_cost numeric)
  loop
    item_count := item_count + 1;
    if purchase_item.inventory_item_id is null or not exists (select 1 from public.inventory_items where id = purchase_item.inventory_item_id and is_active) then raise exception using message = 'ACTIVE_INVENTORY_ITEM_REQUIRED'; end if;
    if purchase_item.quantity is null or purchase_item.quantity <= 0 or purchase_item.unit_cost is null or purchase_item.unit_cost < 0 then raise exception using message = 'PURCHASE_ITEM_VALUES_INVALID'; end if;
    insert into public.purchase_items (purchase_id, inventory_item_id, quantity, unit_cost) values (purchase_record.id, purchase_item.inventory_item_id, purchase_item.quantity, purchase_item.unit_cost);
  end loop;
  if item_count = 0 then raise exception using message = 'PURCHASE_WITHOUT_ITEMS'; end if;
  select * into purchase_record from public.purchases where id = purchase_record.id;
  return purchase_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_recipe_draft(p_company_id uuid, p_name text, p_yield_quantity numeric, p_yield_unit text, p_yield_weight_g numeric, p_notes text, p_items jsonb)
 RETURNS recipes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare recipe_record public.recipes; version_id uuid; recipe_item record; item_count integer := 0;
begin
  if (select auth.uid()) is null then raise exception using message = 'AUTHORIZATION_REQUIRED'; end if;
  if not exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin') then raise exception using message = 'ADMIN_AUTHORIZATION_REQUIRED'; end if;
  if not exists (select 1 from public.companies where id = p_company_id and is_active) then raise exception using message = 'ACTIVE_COMPANY_REQUIRED'; end if;
  if p_yield_quantity is null or p_yield_quantity <= 0 or p_yield_unit not in ('g','ml','un') then raise exception using message = 'RECIPE_YIELD_INVALID'; end if;
  insert into public.recipes(company_id, name, notes) values (p_company_id, btrim(p_name), nullif(btrim(coalesce(p_notes, '')), '')) returning * into recipe_record;
  insert into public.recipe_versions(recipe_id, version_number, yield_quantity, yield_unit, yield_weight_g, notes, created_by) values (recipe_record.id, 1, p_yield_quantity, p_yield_unit, p_yield_weight_g, nullif(btrim(coalesce(p_notes, '')), ''), (select auth.uid())) returning id into version_id;
  for recipe_item in select * from jsonb_to_recordset(coalesce(p_items, '[]'::jsonb)) as x(inventory_item_id uuid, quantity_base numeric)
  loop
    item_count := item_count + 1;
    if recipe_item.inventory_item_id is null or not exists (select 1 from public.inventory_items where id = recipe_item.inventory_item_id and is_active) or recipe_item.quantity_base is null or recipe_item.quantity_base <= 0 then raise exception using message = 'RECIPE_INGREDIENT_INVALID'; end if;
    insert into public.recipe_version_ingredients(recipe_version_id, inventory_item_id, quantity_base) values (version_id, recipe_item.inventory_item_id, recipe_item.quantity_base);
  end loop;
  if item_count = 0 then raise exception using message = 'RECIPE_WITHOUT_INGREDIENTS'; end if;
  return recipe_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_recipe_version(p_recipe_id uuid, p_yield_quantity numeric, p_yield_unit text, p_yield_weight_g numeric, p_notes text, p_items jsonb)
 RETURNS recipe_versions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare recipe_record public.recipes; version_record public.recipe_versions; recipe_item record; next_version integer; item_count integer := 0;
begin
  if (select auth.uid()) is null then raise exception using message = 'AUTHORIZATION_REQUIRED'; end if;
  if not exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin') then raise exception using message = 'ADMIN_AUTHORIZATION_REQUIRED'; end if;
  select * into recipe_record from public.recipes where id = p_recipe_id for update;
  if not found then raise exception using message = 'RECIPE_NOT_FOUND'; end if;
  select coalesce(max(version_number), 0) + 1 into next_version from public.recipe_versions where recipe_id = p_recipe_id;
  insert into public.recipe_versions(recipe_id, version_number, yield_quantity, yield_unit, yield_weight_g, notes, created_by) values (p_recipe_id, next_version, p_yield_quantity, p_yield_unit, p_yield_weight_g, nullif(btrim(coalesce(p_notes, '')), ''), (select auth.uid())) returning * into version_record;
  for recipe_item in select * from jsonb_to_recordset(coalesce(p_items, '[]'::jsonb)) as x(inventory_item_id uuid, quantity_base numeric)
  loop
    item_count := item_count + 1;
    if recipe_item.inventory_item_id is null or not exists (select 1 from public.inventory_items where id = recipe_item.inventory_item_id and is_active) or recipe_item.quantity_base is null or recipe_item.quantity_base <= 0 then raise exception using message = 'RECIPE_INGREDIENT_INVALID'; end if;
    insert into public.recipe_version_ingredients(recipe_version_id, inventory_item_id, quantity_base) values (version_record.id, recipe_item.inventory_item_id, recipe_item.quantity_base);
  end loop;
  if item_count = 0 then raise exception using message = 'RECIPE_WITHOUT_INGREDIENTS'; end if;
  return version_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_sale_draft(p_company_id uuid, p_customer_id uuid, p_scheduled_for timestamp with time zone, p_delivery_address text, p_apartment text, p_notes text, p_items jsonb)
 RETURNS sales
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare sale_record public.sales; sale_item record; item_count integer := 0; company_check boolean;
begin
  if (select auth.uid()) is null then raise exception using message = 'AUTHORIZATION_REQUIRED'; end if;
  if not exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin') then raise exception using message = 'ADMIN_AUTHORIZATION_REQUIRED'; end if;
  select is_active into company_check from public.companies where id = p_company_id;
  if coalesce(company_check, false) = false then raise exception using message = 'ACTIVE_COMPANY_REQUIRED'; end if;
  if not exists (select 1 from public.customers where id = p_customer_id and is_active) then raise exception using message = 'ACTIVE_CUSTOMER_REQUIRED'; end if;
  insert into public.sales(company_id, customer_id, scheduled_for, delivery_address_snapshot, apartment_snapshot, notes, created_by)
  values (p_company_id, p_customer_id, p_scheduled_for, nullif(btrim(coalesce(p_delivery_address, '')), ''), nullif(btrim(coalesce(p_apartment, '')), ''), nullif(btrim(coalesce(p_notes, '')), ''), (select auth.uid())) returning * into sale_record;
  for sale_item in select * from jsonb_to_recordset(coalesce(p_items, '[]'::jsonb)) as x(product_variant_id uuid, quantity integer)
  loop
    item_count := item_count + 1;
    if sale_item.quantity is null or sale_item.quantity <= 0 or not exists (select 1 from public.product_variants pv join public.products p on p.id = pv.product_id where pv.id = sale_item.product_variant_id and pv.is_active and p.company_id = p_company_id and p.is_active) then raise exception using message = 'SALE_ITEM_INVALID'; end if;
    insert into public.sale_items(sale_id, product_variant_id, quantity) values (sale_record.id, sale_item.product_variant_id, sale_item.quantity);
  end loop;
  if item_count = 0 then raise exception using message = 'SALE_WITHOUT_ITEMS'; end if;
  return sale_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_published_recipe_ingredient_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare version_status text;
begin
  select status into version_status from public.recipe_versions where id = coalesce(new.recipe_version_id, old.recipe_version_id);
  if version_status = 'published' then raise exception using message = 'PUBLISHED_RECIPE_INGREDIENTS_IMMUTABLE'; end if;
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_published_recipe_version_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if old.status = 'published' and (new.status <> 'archived' or new.recipe_id is distinct from old.recipe_id or new.version_number is distinct from old.version_number or new.yield_quantity is distinct from old.yield_quantity or new.yield_unit is distinct from old.yield_unit or new.yield_weight_g is distinct from old.yield_weight_g or new.notes is distinct from old.notes) then
    raise exception using message = 'PUBLISHED_RECIPE_VERSION_IMMUTABLE';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_received_purchase_item_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare purchase_status text;
begin
  select status into purchase_status from public.purchases where id = coalesce(new.purchase_id, old.purchase_id);
  if purchase_status = 'received' then raise exception using message = 'RECEIVED_PURCHASE_ITEMS_IMMUTABLE'; end if;
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_recipe_version(p_version_id uuid)
 RETURNS recipe_versions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare version_record public.recipe_versions;
begin
  if (select auth.uid()) is null then raise exception using message = 'AUTHORIZATION_REQUIRED'; end if;
  if not exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin') then raise exception using message = 'ADMIN_AUTHORIZATION_REQUIRED'; end if;
  select * into version_record from public.recipe_versions where id = p_version_id for update;
  if not found then raise exception using message = 'RECIPE_VERSION_NOT_FOUND'; end if;
  if version_record.status = 'published' then return version_record; end if;
  update public.recipe_versions set status = 'archived' where recipe_id = version_record.recipe_id and status = 'published';
  update public.recipe_version_ingredients rvi
  set unit_cost_snapshot = case when ii.average_unit_cost > 0 then ii.average_unit_cost else null end,
      cost_snapshot_at = timezone('utc', now())
  from public.inventory_items ii
  where rvi.recipe_version_id = p_version_id and ii.id = rvi.inventory_item_id;
  update public.recipe_versions set status = 'published', published_at = timezone('utc', now()) where id = p_version_id returning * into version_record;
  return version_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.receive_purchase(p_purchase_id uuid)
 RETURNS purchases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  purchase_record public.purchases;
  purchase_item record;
  item_count integer := 0;
begin
  if (select auth.uid()) is null then raise exception using message = 'AUTHORIZATION_REQUIRED'; end if;
  if not exists (select 1 from public.profiles where profiles.id = (select auth.uid()) and profiles.role = 'admin') then raise exception using message = 'ADMIN_AUTHORIZATION_REQUIRED'; end if;
  select * into purchase_record from public.purchases where id = p_purchase_id for update;
  if not found then raise exception using message = 'PURCHASE_NOT_FOUND'; end if;
  if purchase_record.status = 'received' then return purchase_record; end if;
  if purchase_record.status = 'cancelled' then raise exception using message = 'CANCELLED_PURCHASE'; end if;

  for purchase_item in
    select pi.*, ii.name as item_name, ii.unit as item_unit
    from public.purchase_items pi join public.inventory_items ii on ii.id = pi.inventory_item_id
    where pi.purchase_id = p_purchase_id
    order by pi.created_at, pi.id
  loop
    item_count := item_count + 1;
    if purchase_item.quantity <= 0 or purchase_item.unit_cost < 0 then raise exception using message = 'INVALID_PURCHASE_ITEM'; end if;
    perform public.register_purchase_inventory_movement(purchase_item.inventory_item_id, purchase_item.quantity, purchase_item.unit_cost, 'Compra ' || p_purchase_id::text || ' recebida', purchase_item.receipt_operation_key, p_purchase_id);
  end loop;
  if item_count = 0 then raise exception using message = 'PURCHASE_WITHOUT_ITEMS'; end if;

  update public.purchases set status = 'received', received_at = timezone('utc', now()), received_by = (select auth.uid()), updated_at = timezone('utc', now()) where id = p_purchase_id returning * into purchase_record;
  return purchase_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_purchase_inventory_movement(p_inventory_item_id uuid, p_quantity numeric, p_unit_cost numeric, p_reason text, p_operation_key uuid, p_purchase_id uuid)
 RETURNS inventory_movements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  movement public.inventory_movements;
begin
  if p_operation_key is null then
    raise exception using message = 'PURCHASE_OPERATION_KEY_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.purchases p
    join public.purchase_items pi on pi.purchase_id = p.id
    where p.id = p_purchase_id
      and p.status in ('draft', 'ordered')
      and pi.inventory_item_id = p_inventory_item_id
      and pi.quantity = p_quantity
      and pi.unit_cost = p_unit_cost
      and pi.receipt_operation_key = p_operation_key
  ) then
    raise exception using message = 'PURCHASE_MOVEMENT_ORIGIN_INVALID';
  end if;

  movement := public.register_inventory_movement(
    p_inventory_item_id,
    'manual_in',
    p_quantity,
    p_unit_cost,
    p_reason,
    p_operation_key
  );

  update public.inventory_movements
  set source_type = 'purchase', source_id = p_purchase_id
  where id = movement.id;

  select * into movement
  from public.inventory_movements
  where id = movement.id;

  return movement;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_purchase_payment(p_purchase_id uuid, p_amount numeric, p_payment_method text, p_notes text DEFAULT NULL::text, p_operation_key uuid DEFAULT NULL::uuid)
 RETURNS purchase_payments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare purchase_record public.purchases; payment public.purchase_payments; operation_payment public.purchase_payments; paid_total numeric; generated_operation_key uuid;
begin
  if (select auth.uid()) is null then raise exception using message = 'AUTHORIZATION_REQUIRED'; end if;
  if not exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin') then raise exception using message = 'ADMIN_AUTHORIZATION_REQUIRED'; end if;
  if p_amount is null or p_amount <= 0 then raise exception using message = 'PAYMENT_AMOUNT_INVALID'; end if;
  if p_payment_method not in ('pix', 'cash', 'card', 'other') then raise exception using message = 'PAYMENT_METHOD_INVALID'; end if;
  generated_operation_key := coalesce(p_operation_key, gen_random_uuid());
  select * into operation_payment from public.purchase_payments pp where pp.operation_key = generated_operation_key;
  if found then return operation_payment; end if;
  select * into purchase_record from public.purchases where id = p_purchase_id for update;
  if not found then raise exception using message = 'PURCHASE_NOT_FOUND'; end if;
  if purchase_record.status = 'cancelled' then raise exception using message = 'CANCELLED_PURCHASE'; end if;
  paid_total := coalesce((select sum(amount) from public.purchase_payments where purchase_id = p_purchase_id), 0);
  if paid_total + p_amount > purchase_record.total_amount then raise exception using message = 'PAYMENT_EXCEEDS_BALANCE'; end if;
  insert into public.purchase_payments(purchase_id, amount, payment_method, notes, created_by, operation_key) values (p_purchase_id, p_amount, p_payment_method, nullif(btrim(coalesce(p_notes, '')), ''), (select auth.uid()), generated_operation_key) returning * into payment;
  update public.purchases set payment_status = case when paid_total + p_amount >= total_amount then 'paid' else 'partial' end, updated_at = timezone('utc', now()) where id = p_purchase_id;
  return payment;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_sale_stock_movement(p_inventory_item_id uuid, p_quantity numeric, p_unit_cost numeric, p_reason text, p_operation_key uuid, p_sale_id uuid)
 RETURNS inventory_movements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  movement public.inventory_movements;
begin
  if p_operation_key is null then
    raise exception using message = 'SALE_OPERATION_KEY_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.sale_item_ingredient_snapshots sis
    join public.sale_items si on si.id = sis.sale_item_id
    join public.sales s on s.id = si.sale_id
    where s.id = p_sale_id
      and s.order_status = 'draft'
      and sis.inventory_item_id = p_inventory_item_id
      and sis.quantity_consumed = p_quantity
      and coalesce(sis.unit_cost_snapshot, 0) = coalesce(p_unit_cost, 0)
  ) then
    raise exception using message = 'SALE_MOVEMENT_ORIGIN_INVALID';
  end if;

  movement := public.register_inventory_movement(
    p_inventory_item_id,
    'manual_out',
    p_quantity,
    p_unit_cost,
    p_reason,
    p_operation_key
  );

  update public.inventory_movements
  set source_type = 'sale', source_id = p_sale_id
  where id = movement.id;

  select * into movement
  from public.inventory_movements
  where id = movement.id;

  return movement;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_variant_recipe_company()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare product_company uuid; recipe_company uuid;
begin
  if new.recipe_version_id is null then return new; end if;
  select company_id into product_company from public.products where id = new.product_id;
  select r.company_id into recipe_company from public.recipe_versions rv join public.recipes r on r.id = rv.recipe_id where rv.id = new.recipe_version_id;
  if product_company is null or recipe_company is null or product_company <> recipe_company then raise exception using message = 'PRODUCT_RECIPE_COMPANY_MISMATCH'; end if;
  return new;
end;
$function$
